solutionCode:
pub fn etiqueta(a: i32, b: i32) -> String {
    format!("pedido {a} + {b} = {}", a + b)
}

testsCode:
use desafio::etiqueta;

// a etiqueta de 7 e 3 mostra a conta e o total 10
#[test]
fn testa_a_etiqueta_de_sete_e_tres() {
    assert_eq!(etiqueta(7, 3), "pedido 7 + 3 = 10");
}

// a etiqueta de 12 e 1 mostra a conta e o total 13
#[test]
fn testa_a_etiqueta_de_doze_e_um() {
    assert_eq!(etiqueta(12, 1), "pedido 12 + 1 = 13");
}

// a etiqueta com parcela zero: 0 e 5 dão total 5
#[test]
fn testa_a_etiqueta_com_parcela_zero() {
    assert_eq!(etiqueta(0, 5), "pedido 0 + 5 = 5");
}
